			IRI limit = vf.createIRI(EX, "limit");
			for (int i = 0; i < 40; i++) {
				conn.add(vf.createIRI(EX, "outer" + i), limit, vf.createLiteral(i % 5 == 0 ? i * 10 : i * 10 + 2));
			}
